\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}
\newtheorem{proposition}{Proposition}
\newtheorem{corollary}{Corollary}
\theoremstyle{definition}
\newtheorem{definition}{Definition}
\newtheorem{remark}{Remark}

\newcommand{\Univ}{\operatorname{Universal}}
\newcommand{\base}{\mathrm{base}}
\newcommand{\PS}{\mathcal{P}}

\title{Universal Mathematics: The Invariant Core Shared by Every Consistent Theory}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
We give a precise, foundation-agnostic answer to the question of whether a
non-human intelligence---alien, artificial, or independently evolved---would
discover the same mathematics we do. Modeling logical consequence by a Tarski
\emph{consequence operator} $C$ (equivalently, a closure operator on the
powerset of statements), we define the \emph{universal mathematics} of a base
theory to be the intersection of the theorem-sets of all consistent theories
extending it. Our two principal results are: (i) \emph{universality of the
base}---every theorem of the base is a theorem of every consistent extension;
and (ii) \emph{the universal core equals the base}---for a consistent base
theory, its universal mathematics coincides exactly with its own deductive
closure. Reading the base as the axioms of arithmetic, (i) is the precise sense
in which arithmetic is universal. We supplement these with structural results
and exhibit an explicit model demonstrating that consistent extensions can be
strictly larger than the base while the universal core is unchanged.
\end{abstract}

\maketitle

\section{Introduction}

The intuition that mathematics is ``universal''---that it would be rediscovered
by any sufficiently advanced intelligence---usually resists formalization
because ``the same mathematics'' is left undefined. Contingent features of human
practice (notation, choice of primitives, aesthetic emphasis) are plainly not
universal. What could plausibly be universal is the \emph{logical content}: what
follows from what.

We isolate that content by reasoning about \emph{theories}: sets of assumptions
closed under a deduction operator. The central device is the \emph{universal
core} of a base theory---the set of statements that every consistent extension
of the base must prove. The main finding is that this core is completely
determined: for a consistent base, it is exactly the base's own deductive
closure. Disagreement between consistent minds is therefore never about
consequences of shared assumptions; it is always about which assumptions to
adopt.

\section{The consequence operator}

Fix a type $S$ whose elements are \emph{statements}; subsets of $S$ are
\emph{theories}.

\begin{definition}[Consequence operator]
A \emph{consequence operator} on $S$ is a map $C:\PS(S)\to\PS(S)$ such that for
all $\Gamma,\Delta$:
\begin{enumerate}
  \item \textbf{Inclusion:} $\Gamma\subseteq C(\Gamma)$;
  \item \textbf{Monotonicity:} $\Gamma\subseteq\Delta \implies C(\Gamma)\subseteq C(\Delta)$;
  \item \textbf{Idempotence (cut):} $C(C(\Gamma))\subseteq C(\Gamma)$.
\end{enumerate}
We read $C(\Gamma)$ as the deductive closure of $\Gamma$. These are Tarski's
axioms for a consequence relation; they refer to no syntax, negation, or
connective.
\end{definition}

\begin{proposition}[Genuine idempotence]
For every theory $\Gamma$, $C(C(\Gamma))=C(\Gamma)$.
\end{proposition}
\begin{proof}
$C(C(\Gamma))\subseteq C(\Gamma)$ is axiom (3), while $C(\Gamma)\subseteq
C(C(\Gamma))$ is axiom (1) applied to $C(\Gamma)$. Antisymmetry gives equality.
\end{proof}

\begin{proposition}[Consequence $=$ closure]
A consequence operator is precisely a closure operator on the complete lattice
$(\PS(S),\subseteq)$. Hence the closed theories ($\Gamma$ with $C(\Gamma)=\Gamma$)
form a complete lattice under inclusion.
\end{proposition}
\begin{proof}[Proof sketch]
Axioms (1)--(3) are extensivity, monotonicity, and idempotence once idempotence
is upgraded to equality. The closed sets of a closure operator on a complete
lattice form a complete lattice.
\end{proof}

\section{Consistency and the universal core}

\begin{definition}[Consistency]
A theory $\Gamma$ is \emph{consistent} if $C(\Gamma)\neq S$; an inconsistent
theory is one whose deductive closure is everything.
\end{definition}

\begin{definition}[Universal mathematics]
For a base theory $\base\subseteq S$,
\[
\Univ(\base)=\bigcap\bigl\{\,T : \exists\,\Delta,\ \base\subseteq\Delta,\
\Delta\text{ consistent},\ T=C(\Delta)\,\bigr\}.
\]
A statement lies in the universal core iff it is a theorem of every consistent
extension of the base.
\end{definition}

\section{Main results}

\begin{theorem}[Universality of the base]
If $\base\subseteq\Delta$ and $\Delta$ is consistent, then
$C(\base)\subseteq C(\Delta)$.
\end{theorem}
\begin{proof}
Immediate from monotonicity applied to $\base\subseteq\Delta$.
\end{proof}

\begin{remark}
Taking $\base$ to be the axioms of arithmetic, this says any consistent system
containing arithmetic proves everything arithmetic proves: no consistent
extension can retract an arithmetical theorem.
\end{remark}

\begin{theorem}[The universal core equals the base]
If $\base$ is consistent, then $\Univ(\base)=C(\base)$.
\end{theorem}
\begin{proof}
$(\supseteq)$ Let $x\in C(\base)$ and let $T=C(\Delta)$ be any member of the
defining family, so $\base\subseteq\Delta$ with $\Delta$ consistent. By the
previous theorem $x\in C(\base)\subseteq C(\Delta)=T$; as $T$ was arbitrary,
$x\in\Univ(\base)$.

$(\subseteq)$ Since $\base$ is consistent and $\base\subseteq\base$, the set
$C(\base)$ is itself a member of the family (take $\Delta=\base$). An
intersection is contained in each member, so $\Univ(\base)\subseteq C(\base)$.
Antisymmetry gives equality.
\end{proof}

\begin{theorem}[Downward inheritance of consistency]
If $\base\subseteq\Delta$ and $\Delta$ is consistent, then $\base$ is
consistent.
\end{theorem}
\begin{proof}
Contrapositive: if $C(\base)=S$ then by monotonicity $S\subseteq C(\Delta)$, so
$C(\Delta)=S$ and $\Delta$ is inconsistent.
\end{proof}

\section{Structural properties of the core}

\begin{proposition}[The core is deductively closed]
If $\base$ is consistent, then $C(\Univ(\base))=\Univ(\base)$.
\end{proposition}
\begin{proof}
By the core-equals-base theorem the core is $C(\base)$, and
$C(C(\base))=C(\base)$.
\end{proof}

\begin{proposition}[The core is consistent]
If $\base$ is consistent, then $\Univ(\base)$ is consistent.
\end{proposition}
\begin{proof}
$C(\Univ(\base))=C(C(\base))=C(\base)\neq S$.
\end{proof}

\begin{proposition}[Monotonicity of the core]
If $\base\subseteq\base'$, then $\Univ(\base)\subseteq\Univ(\base')$.
\end{proposition}
\begin{proof}
Let $x\in\Univ(\base)$ and $T=C(\Delta)$ a member of the family for $\base'$, so
$\base'\subseteq\Delta$ with $\Delta$ consistent. Then $\base\subseteq\Delta$,
so $C(\Delta)$ is also in the family for $\base$; hence $x\in C(\Delta)=T$.
\end{proof}

\begin{remark}
A larger base admits fewer consistent extensions, so a smaller family is
intersected; yet each such extension already constrained the smaller core. By
the core-equals-base theorem both cores are simply $C(\base)\subseteq C(\base')$.
\end{remark}

\section{A concrete model}

\begin{definition}[Identity consequence system]
On $S=\mathbb{N}$, let $C(\Gamma)=\Gamma$. Axioms (1)--(3) hold trivially.
\end{definition}

\begin{proposition}
The base $\{0\}$ is consistent, since $C(\{0\})=\{0\}\neq\mathbb{N}$.
\end{proposition}

\begin{proposition}[Strict extension, invariant core]
$\{0\}\subseteq\{0,1\}$ is a strict extension, both are consistent, and they
disagree on the statement $1$. Yet $\Univ(\{0\})=C(\{0\})=\{0\}$, so the
disagreement lies strictly above the universal core.
\end{proposition}

\section{Discussion and future directions}

The framework converts ``mathematics is universal'' into a theorem with sharp
scope: universality is relative to a base and to consistency, and within that
scope the universal content is exactly the deductive closure of the base. Three
directions extend this: (1) showing the universal core is the meet, in the
lattice of closed theories, of the maximal consistent extensions of the base
under compactness; (2) using negation-completeness to identify the core with the
theory of a space of maximal consistent models; and (3) quantifying independence
as the gap between the core and the individual maximal completions.

\section{Conclusion}

For a consistent base, the invariant core across all consistent extensions is
exactly the base's deductive closure. Any two consistent reasoners sharing a
foundation share exactly its closure---no more, no less---so mathematical
disagreement is always about axioms, never about their consequences.

\end{document}

