from typing import Callable, FrozenSet, Iterator

Theory = FrozenSet[int]

def powerset(u: FrozenSet[int]) -> Iterator[Theory]:
    e = sorted(u)
    for r in range(len(e)+1):
        for c in combinations(e, r):
            yield frozenset(c)

# Threshold system: assuming 1 forces deducing 2 (real deduction).
u = frozenset({0,1,2,3})
def C(g: Theory) -> Theory:
    s = set(g)
    if 1 in s: s.add(2)
    return frozenset(s & set(u))

base = frozenset({1})
# Theorem A: every consistent extension proves C(base).
ok = all(C(base) <= C(d) for d in powerset(u) if base <= d and C(d) != u)
print("C(base) =", set(C(base)))
print("Theorem A (every consistent extension proves C(base)):", ok)

