def powerset(u: FrozenSet[int]) -> Iterator[Theory]:
    e = sorted(u)
    for r in range(len(e)+1):
        for c in combinations(e, r):
            yield frozenset(c)

# Explosive system: holding {1,2} proves everything (inconsistency).
u = frozenset({0,1,2})
def C(g: Theory) -> Theory:
    return u if frozenset({1,2}) <= g else g

# Theorem C: subtheories of a consistent theory are consistent.
violations = 0
for d in powerset(u):
    if C(d) != u:  # d consistent
        for g in powerset(d):
            if C(g) == u:
                violations += 1
print("Theorem C holds (downward consistency):", violations == 0)

