def verify_closure_axioms(C: Callable[[Theory], Theory], u: FrozenSet[int]) -> bool:
    subsets: List[Theory] = list(powerset(u))
    for g in subsets:
        if not g <= C(g):            # inclusion
            return False
        if C(C(g)) != C(g):          # idempotence
            return False
    for g in subsets:
        for d in subsets:
            if g <= d and not (C(g) <= C(d)):  # monotonicity
                return False
    return True

