from typing import Callable, FrozenSet, Iterator, List, Set

Theory = FrozenSet[int]

def powerset(u: FrozenSet[int]) -> Iterator[Theory]:
    e: List[int] = sorted(u)
    for r in range(len(e) + 1):
        for c in combinations(e, r):
            yield frozenset(c)

def universal_core(C: Callable[[Theory], Theory], u: FrozenSet[int], base: Theory) -> Theory:
    core: Set[int] = set(u)
    found = False
    for d in powerset(u):
        if base <= d and C(d) != u:   # d is a consistent extension of base
            core &= set(C(d))
            found = True
    return frozenset(core) if found else u  # empty family -> universe

