from itertools import combinations
from typing import Callable, FrozenSet, Iterator, List

Theory = FrozenSet[int]

def powerset(u: FrozenSet[int]) -> Iterator[Theory]:
    e: List[int] = sorted(u)
    for r in range(len(e) + 1):
        for c in combinations(e, r):
            yield frozenset(c)

def is_consistent(C: Callable[[Theory], Theory], u: FrozenSet[int], g: Theory) -> bool:
    return C(g) != u

def certified_consistent_subtheories(C: Callable[[Theory], Theory],
                                     u: FrozenSet[int], g: Theory) -> List[Theory]:
    # If g is consistent, Theorem C certifies every subtheory is consistent
    # WITHOUT recomputation.
    if not is_consistent(C, u, g):
        raise ValueError("theory is inconsistent")
    return list(powerset(g))

