# Lattice of theories over {0,1,2}, colored by consistency, showing the
# universal core of base {0} under an explosive operator (contradiction {1,2}).
import matplotlib.pyplot as plt
from itertools import combinations

ground = [0, 1, 2]
def powerset(e):
    for r in range(len(e)+1):
        for c in combinations(e, r):
            yield frozenset(c)

U = frozenset(ground)
def C(g):
    return U if frozenset({1,2}) <= g else g

subsets = list(powerset(ground))
levels = {}
for s in subsets:
    levels.setdefault(len(s), []).append(s)

pos = {}
for lvl, sets in levels.items():
    for i, s in enumerate(sorted(sets, key=lambda x: sorted(x))):
        pos[s] = (i - (len(sets)-1)/2, lvl)

fig, ax = plt.subplots(figsize=(8, 6))
for s in subsets:
    for t in subsets:
        if s < t and len(t) == len(s) + 1:
            x1, y1 = pos[s]; x2, y2 = pos[t]
            ax.plot([x1, x2], [y1, y2], color="lightgray", zorder=1)
for s in subsets:
    x, y = pos[s]
    consistent = C(s) != U
    ax.scatter([x], [y], s=900,
               color="#2ca02c" if consistent else "#d62728", zorder=2)
    ax.text(x, y, "{" + ",".join(map(str, sorted(s))) + "}" if s else "{}",
            ha="center", va="center", fontsize=8, color="white")
ax.set_title("Theory lattice over {0,1,2}: green = consistent, red = inconsistent")
ax.axis("off")
plt.tight_layout()
plt.savefig("viz_lattice.png", dpi=140)
print("saved viz_lattice.png")

# Visualizes monotonicity of the universal core: as the base grows along a
# chain, the universal core grows monotonically (Proposition 5.3).
import matplotlib.pyplot as plt
from itertools import combinations

ground = [0, 1, 2, 3]
U = frozenset(ground)
def powerset(e):
    for r in range(len(e)+1):
        for c in combinations(e, r):
            yield frozenset(c)
def C(g):
    s = set(g)
    if 0 in s: s.add(1)
    if 1 in s: s.add(2)
    return frozenset(s & set(ground))
def core(base):
    c = set(U); found = False
    for d in powerset(ground):
        if base <= d and C(d) != U:
            c &= set(C(d)); found = True
    return frozenset(c) if found else U

chain = [frozenset(), frozenset({0}), frozenset({0,1}), frozenset({0,1,2})]
labels = ["{}", "{0}", "{0,1}", "{0,1,2}"]
sizes = [len(core(b)) for b in chain]

fig, ax = plt.subplots(figsize=(8, 5))
ax.plot(range(len(chain)), sizes, marker="o", linewidth=2, color="#9467bd")
for i, s in enumerate(sizes):
    ax.annotate(str(s), (i, s), textcoords="offset points", xytext=(0, 8), ha="center")
ax.set_xticks(range(len(chain))); ax.set_xticklabels(labels)
ax.set_ylabel("|Universal(base)|")
ax.set_title("Monotonicity: larger base -> larger (or equal) universal core")
plt.tight_layout()
plt.savefig("viz_monotone.png", dpi=140)
print("saved viz_monotone.png")
